css:
.eow-ky .elementor-widget-container{font-size:16px;line-height:30px;color:#6b6460}
.eow-ky p{margin:0 0 20px}
.eow-ky h2{font-size:20px;line-height:28px;font-weight:600;color:#333;margin:10px 0 14px}
.eow-ky h3{font-size:17px;line-height:26px;font-weight:600;color:#333;margin:18px 0 6px}
.eow-ky ul,.eow-ky ol{margin:0 0 20px 22px;padding:0}
.eow-ky li{margin:0 0 6px}
.eow-ky a{text-decoration:underline}
.eow-ky-acc{display:grid;gap:12px;margin:4px 0 24px}
.eow-ky-acc details{background:#fff;border:1px solid #e4e4e4;border-radius:10px;overflow:hidden;box-shadow:0 1px 2px rgba(0,0,0,.04);transition:box-shadow .25s,border-color .25s,transform .25s}
.eow-ky-acc details:hover{border-color:#cfcfcf;box-shadow:0 8px 22px rgba(0,0,0,.08);transform:translateY(-1px)}
.eow-ky-acc details[open]:not(.closing){border-color:#3a3a3a;box-shadow:0 12px 28px rgba(0,0,0,.14);transform:none}
.eow-ky-acc summary{list-style:none;display:flex;align-items:center;gap:14px;padding:16px 18px;cursor:pointer;transition:background .25s}
.eow-ky-acc summary::-webkit-details-marker{display:none}
.eow-ky-acc details[open]:not(.closing) summary{background:#3a3a3a}
.eow-ky-q{flex:0 0 30px;height:30px;border-radius:8px;background:#ffea00;color:#333;font-weight:700;font-size:14px;line-height:30px;text-align:center}
.eow-ky-acc summary h3{flex:1;margin:0;font-size:16px;line-height:24px;font-weight:600;color:#333;transition:color .25s}
.eow-ky-acc details[open]:not(.closing) summary h3{color:#fff}
.eow-ky-acc summary:focus-visible{outline:2px solid #ffea00;outline-offset:-2px}
.eow-ky-ic{flex:0 0 30px;height:30px;border-radius:50%;background:#f1f1f1;position:relative;transition:background .25s,transform .3s}
.eow-ky-ic::before,.eow-ky-ic::after{content:"";position:absolute;left:50%;top:50%;width:12px;height:2px;border-radius:2px;background:#333;transform:translate(-50%,-50%)}
.eow-ky-ic::after{transform:translate(-50%,-50%) rotate(90deg)}
.eow-ky-acc details[open]:not(.closing) .eow-ky-ic{background:#ffea00;transform:rotate(45deg)}
.eow-ky-ans{overflow:hidden;transition:height .32s ease}
.eow-ky-ans-in{padding:16px 18px 18px 62px;border-left:4px solid #ffea00;margin-left:0}
.eow-ky-ans-in p{margin:0}
@media (max-width:767px){.eow-ky-ans-in{padding-left:18px}.eow-ky-acc summary{padding:14px}}
@media (prefers-reduced-motion:reduce){.eow-ky-acc details,.eow-ky-acc summary,.eow-ky-ic,.eow-ky-ans{transition:none}}
@media (min-width:1025px){
 body.elementor-page-2039 .opal-wrapper,
 body.elementor-page-2039 .site,
 body.elementor-page-2039 .site-content-contain{overflow:clip!important}
 .eow-ky-sticky > .elementor-widget-wrap{position:sticky;top:122px;align-self:flex-start}
}

